fn no_metadata_validate_archived_payload(
    archived: &ArchivedMathildeTransportResponseV1PayloadNoMetadata,
    expected_rows: u64,
) -> Result<()> {
    if archived.schema_version.to_native() != NO_METADATA_SCHEMA_VERSION_VALUE {
        return Err(TransportError::SchemaVersionMismatch {
            observed: archived.schema_version.to_native(),
            expected: NO_METADATA_SCHEMA_VERSION_VALUE,
        });
    }
    let expected = usize::try_from(expected_rows)
        .map_err(|err| TransportError::MalformedArchive(err.to_string()))?;
    if archived.rows.len() != expected {
        return Err(TransportError::RowCountMismatch {
            observed: archived.rows.len(),
            expected: expected_rows,
        });
    }
    Ok(())
}

fn no_metadata_inspect_archived_rows(
    archived: &ArchivedMathildeTransportResponseV1PayloadNoMetadata,
) -> Result<BinaryInspection> {
    let mut semantic_checksum = fnv1a64("mathilde.bar.v1.no_metadata".as_bytes());
    let mut minimal_projection_checksum = semantic_checksum;
    for row in archived.rows.iter() {
        semantic_checksum = no_metadata_checksum_archived_row(semantic_checksum, row);
        minimal_projection_checksum =
            no_metadata_checksum_archived_row(minimal_projection_checksum, row);
    }
    Ok(BinaryInspection {
        row_count: archived.rows.len(),
        semantic_checksum,
        minimal_projection_checksum,
    })
}
