fn ohlcv_only_validate_archived_payload(
    archived: &ArchivedMathildeTransportResponseV1PayloadOhlcvOnly,
    expected_rows: u64,
) -> Result<()> {
    if archived.schema_version.to_native() != OHLCV_ONLY_SCHEMA_VERSION_VALUE {
        return Err(TransportError::SchemaVersionMismatch {
            observed: archived.schema_version.to_native(),
            expected: OHLCV_ONLY_SCHEMA_VERSION_VALUE,
        });
    }
    let expected = usize::try_from(expected_rows)
        .map_err(|err| TransportError::MalformedArchive(err.to_string()))?;
    if archived.rows.len() != expected {
        return Err(TransportError::RowCountMismatch {
            observed: archived.rows.len(),
            expected: expected_rows,
        });
    }
    Ok(())
}

fn ohlcv_only_inspect_archived_rows(
    archived: &ArchivedMathildeTransportResponseV1PayloadOhlcvOnly,
) -> Result<BinaryInspection> {
    let mut semantic_checksum = fnv1a64("mathilde.bar.v1.ohlcv_only".as_bytes());
    let mut minimal_projection_checksum = semantic_checksum;
    for row in archived.rows.iter() {
        semantic_checksum = ohlcv_only_checksum_archived_row(semantic_checksum, row);
        minimal_projection_checksum =
            ohlcv_only_checksum_archived_row(minimal_projection_checksum, row);
    }
    Ok(BinaryInspection {
        row_count: archived.rows.len(),
        semantic_checksum,
        minimal_projection_checksum,
    })
}
