const _: fn(&ArchivedMathildeTransportResponseV1Payload, usize) -> Result<Vec<u8>> =
    project_ohlcv_only_archived_direct;

impl BarsV1 {
    pub fn project_ohlcv_only(bytes: &[u8], max_response_bytes: usize) -> Result<Vec<u8>> {
        let archived = Self::access_archived(bytes)?;
        project_ohlcv_only_archived_direct(archived, max_response_bytes)
    }

    /// Projects immutable source bytes already validated for this schema.
    ///
    /// # Safety
    /// The caller guarantees that bytes were previously accepted by checked MBT access
    /// for the source schema and then stored or transported without mutation.
    pub unsafe fn project_ohlcv_only_trusted_unchecked(
        bytes: &[u8],
        max_response_bytes: usize,
    ) -> Result<Vec<u8>> {
        let archived = unsafe { Self::access_archived_trusted_unchecked(bytes)? };
        project_ohlcv_only_archived_direct(archived, max_response_bytes)
    }
}

fn project_ohlcv_only_archived_direct(
    archived: &ArchivedMathildeTransportResponseV1Payload,
    max_response_bytes: usize,
) -> Result<Vec<u8>> {
    let row_count = archived.rows.len() as u64;
    let payload = BarsV1OhlcvOnlyProjectionPayloadRef {
        schema_version: OHLCV_ONLY_SCHEMA_VERSION_VALUE,
        rows: BarsV1OhlcvOnlyProjectionRowsRef {
            rows: &archived.rows,
        },
    };
    let payload_bytes = rkyv::to_bytes::<RkyvError>(&payload)
        .map_err(|_err| TransportError::MalformedArchive(String::new()))?;
    let payload_len = payload_bytes.len();
    let total_len =
        HEADER_LEN
            .checked_add(payload_len)
            .ok_or(TransportError::ResponseTooLarge {
                observed: usize::MAX,
                cap: max_response_bytes,
            })?;
    if total_len > max_response_bytes {
        return Err(TransportError::ResponseTooLarge {
            observed: total_len,
            cap: max_response_bytes,
        });
    }
    let header = TransportHeader::new_with_schema(
        BarsV1OhlcvOnly::header_spec(),
        row_count,
        payload_len as u64,
        fnv1a64(&payload_bytes),
    );
    let mut header_bytes = [0_u8; HEADER_LEN];
    encode_header(&header, &mut header_bytes);
    let mut out = Vec::with_capacity(total_len);
    out.extend_from_slice(&header_bytes);
    out.extend_from_slice(&payload_bytes);
    Ok(out)
}
